#!/usr/bin/env node
/* =========================================================
   HERMES BRIDGE - STDIO MCP PROXY (After Effects + Premiere Pro)
   Registered in a normal Hermes profile (mcp_servers.after_effects /
   mcp_servers.premiere_pro) so EVERY Hermes surface - the panel in
   full mode, Hermes Desktop chat, CLI, Telegram, cron - can drive the
   AE / Premiere project that is open right now.

   The real MCP server lives inside the CEP panel (js/mcp.js, random
   port + bearer token). The panel writes both to endpoint.json in its
   data dir on start and deletes it on close; this proxy re-reads that
   file on every call, so it survives panel/app restarts.

   usage: node hb-mcp-proxy.js ae|ppro
   Same file ships in both extensions (byte-identical).
   ========================================================= */
"use strict";

var fs = require("fs");
var os = require("os");
var path = require("path");
var http = require("http");

var APP = (process.argv[2] || "ae").toLowerCase() === "ppro" ? "ppro" : "ae";
var WIN = process.platform === "win32";
var HOME = os.homedir();
var DATA = WIN
  ? path.join(process.env.APPDATA || path.join(HOME, "AppData", "Roaming"), APP === "ppro" ? "HermesBridgePR" : "HermesBridge")
  : path.join(HOME, "Library", "Application Support", APP === "ppro" ? "HermesBridgePR" : "HermesBridge");
var ENDPOINT = path.join(DATA, "endpoint.json");
var LABEL = APP === "ppro" ? "Premiere Pro" : "After Effects";
var PANEL = APP === "ppro" ? "Hermes Bridge PR" : "Hermes Bridge";

// Tool schemas come straight from the panel's own mcp.js (same folder tree),
// so the list is always in sync with the installed panel version and is
// available even while the app is closed.
var Server = null;
(function loadSchemas() {
  var candidates = [
    path.join(__dirname, "..", "js", "mcp.js"),
    path.join(HOME, "Library", "Application Support", "Adobe", "CEP", "extensions",
      APP === "ppro" ? "com.feugee.hermesbridgepr" : "com.feugee.hermesbridge", "js", "mcp.js")
  ];
  for (var i = 0; i < candidates.length && !Server; i++) {
    try {
      // mcp.js only touches window/document inside functions; under node it
      // attaches to `global`. The ExtendScript side is not loaded here.
      // envato.js first: mcp.js appends its tool schemas at load time.
      try { require(path.join(path.dirname(candidates[i]), "envato-session.js")); } catch (e3) {}
      try { require(path.join(path.dirname(candidates[i]), "envato.js")); } catch (e2) {}
      require(candidates[i]);
      Server = APP === "ppro" ? global.PproMcpServer : global.AeMcpServer;
    } catch (e) { Server = null; }
  }
})();
var TOOLS = (Server && Server.TOOLS) || [];
var INSTRUCTIONS = ((Server && Server.INSTRUCTIONS) || "") +
  " These tools reach the " + LABEL + " project open on this Mac through the " + PANEL + " panel; " +
  "if the app or panel is closed every call says so - then tell the user to open " + LABEL + " and Window > Extensions > " + PANEL + ".";

// Parent + grandparent pid: the panel compares them with the pid of the
// `hermes acp` it spawned (a launcher script may sit in between).
var ANCESTORS = (function () {
  var ids = [process.ppid];
  if (!WIN) {
    try {
      var g = String(require("child_process").execFileSync("ps", ["-o", "ppid=", "-p", String(process.ppid)], { timeout: 2000 })).trim();
      if (g) ids.push(Number(g));
    } catch (e) {}
  }
  return ids.join(",");
})();

function readEndpoint() {
  try {
    var e = JSON.parse(fs.readFileSync(ENDPOINT, "utf8"));
    if (e && e.url && e.token) return e;
  } catch (err) {}
  return null;
}

function closedText(why) {
  return LABEL + " belum bisa dijangkau (" + why + "). Minta user membuka " + LABEL +
    " lalu Window > Extensions > " + PANEL + " (panel harus terbuka), kemudian coba lagi. Jangan pakai osascript sebagai gantinya kecuali user minta.";
}

// One JSON-RPC request to the panel's HTTP MCP server.
function forward(msg, timeoutMs) {
  return new Promise(function (resolve) {
    var ep = readEndpoint();
    if (!ep) return resolve({ closed: closedText("panel tidak terbuka") });
    var body = Buffer.from(JSON.stringify(msg), "utf8");
    var u;
    try { u = new URL(ep.url); } catch (e) { return resolve({ closed: closedText("endpoint rusak") }); }
    var done = false;
    var req = http.request({
      host: u.hostname, port: u.port, path: u.pathname, method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "Content-Length": body.length,
        "Authorization": "Bearer " + ep.token,
        // lets the panel tell its own agent from Hermes Desktop / CLI / Telegram
        "X-HB-Parent-Pid": ANCESTORS
      }
    }, function (res) {
      var chunks = [];
      res.on("data", function (c) { chunks.push(c); });
      res.on("end", function () {
        if (done) return; done = true;
        if (res.statusCode === 401) return resolve({ closed: closedText("token kedaluwarsa, panel baru di-restart") });
        try { resolve({ reply: JSON.parse(Buffer.concat(chunks).toString("utf8")) }); }
        catch (e) { resolve({ closed: closedText("balasan panel tidak terbaca") }); }
      });
    });
    req.setTimeout(timeoutMs || 330000, function () {
      if (done) return; done = true;
      req.destroy();
      resolve({ closed: closedText(LABEL + " tidak menjawab - mungkin sedang render/export atau ada dialog terbuka") });
    });
    req.on("error", function (e) {
      if (done) return; done = true;
      resolve({ closed: closedText(e.code === "ECONNREFUSED" ? "panel sudah ditutup" : e.code || e.message) });
    });
    req.end(body);
  });
}

function send(obj) { process.stdout.write(JSON.stringify(obj) + "\n"); }

// Requests still running when stdin closes are answered before exiting.
var pending = 0, closing = false;
function track(p) {
  if (!p || typeof p.then !== "function") return p;
  pending++;
  return p.then(done, done);
  function done() { if (--pending <= 0 && closing) process.exit(0); }
}

function handle(msg) {
  if (!msg || typeof msg !== "object" || !msg.method) return;
  var id = msg.id, isReq = id !== undefined && id !== null;
  var params = msg.params || {};
  function ok(result) { if (isReq) send({ jsonrpc: "2.0", id: id, result: result }); }

  switch (msg.method) {
    case "initialize":
      return ok({
        protocolVersion: params.protocolVersion || "2025-06-18",
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: APP === "ppro" ? "premiere-pro" : "after-effects", version: "1.0.0" },
        instructions: INSTRUCTIONS
      });
    case "ping":
      return ok({});
    case "tools/list":
      // Tell a live panel which agent listed its tools (boot check), never wait on it.
      forward({ jsonrpc: "2.0", id: "hb-list", method: "tools/list", params: {} }, 2000);
      return ok({ tools: TOOLS });
    case "resources/list": return ok({ resources: [] });
    case "prompts/list": return ok({ prompts: [] });
    case "tools/call":
      // Envato search does not need the app: when the panel is closed, run it
      // here. With the panel open it goes through the panel (cards in chat).
      if (params.name === "envato_search" && global.HBEnvato) {
        return forward({ jsonrpc: "2.0", id: 1, method: "tools/call", params: params }).then(function (r) {
          if (!r.closed && r.reply && r.reply.result) return ok(r.reply.result);
          return global.HBEnvato.search(params.arguments || {}, { previewDir: path.join(DATA, "envato", "previews") }).then(function (res) {
            var text = res.ok ? JSON.stringify(res.data) : (res.infra ? "ERROR: " : "SEARCH ERROR (perbaiki argumen lalu ulangi): ") + res.error;
            ok({ content: [{ type: "text", text: text }], isError: !res.ok && !!res.infra });
          });
        });
      }
      return forward({ jsonrpc: "2.0", id: 1, method: "tools/call", params: params }).then(function (r) {
        if (r.closed) return ok({ content: [{ type: "text", text: "ERROR: " + r.closed }], isError: true });
        if (r.reply && r.reply.error) return ok({ content: [{ type: "text", text: "ERROR: " + (r.reply.error.message || "panel error") }], isError: true });
        return ok(r.reply && r.reply.result ? r.reply.result : { content: [{ type: "text", text: "ERROR: balasan kosong dari panel" }], isError: true });
      });
    default:
      if (isReq) send({ jsonrpc: "2.0", id: id, error: { code: -32601, message: "method not found: " + msg.method } });
  }
}

var buf = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", function (d) {
  buf += d;
  var i;
  while ((i = buf.indexOf("\n")) >= 0) {
    var line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (!line) continue;
    var msg;
    try { msg = JSON.parse(line); } catch (e) { continue; }
    if (Array.isArray(msg)) msg.forEach(function (m) { track(handle(m)); }); else track(handle(msg));
  }
});
process.stdin.on("end", function () { closing = true; if (pending <= 0) process.exit(0); });

files.css/hermes.css:
/* =========================================================
   HERMES BRIDGE - panel-specific styles
   Everything shared (palette, topbar, cards, tiles, checks,
   statusbar, light theme) comes from css/panel.css - untouched.
   ========================================================= */

.card.span { grid-column: 1 / -1; }

/* ---------- chat log ---------- */
.hb-log {
  height: calc(100vh - 330px);
  min-height: 170px;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  margin: 0 -2px 8px;
  padding: 2px;
  user-select: text;
  cursor: auto;
}
.hb-log::-webkit-scrollbar { width: 8px; }
.hb-log::-webkit-scrollbar-track { background: transparent; }
.hb-log::-webkit-scrollbar-thumb { background: #3a3a44; border-radius: 4px; border: 2px solid var(--card); }

.hb-msg {
  margin: 0 0 7px;
  padding: 7px 9px 8px;
  border-radius: 5px;
  border: 1px solid var(--stroke-soft);
  background: var(--tile);
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text);
  overflow-wrap: anywhere;
}
.hb-msg.user {
  margin-left: 22px;
  background: var(--blue-dim);
  border-color: var(--blue-mid);
}
.hb-who {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 3px;
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: var(--orange);
}
.hb-msg.user .hb-who { color: var(--blue); }
.hb-who .t { color: var(--text-muted); font-weight: 400; letter-spacing: 0; }

.hb-body p { margin: 0 0 6px; }
.hb-body p:last-child { margin-bottom: 0; }
.hb-body code {
  font: 10.5px/1.4 Menlo, "SF Mono", monospace;
  background: var(--field);
  border: 1px solid var(--stroke-soft);
  border-radius: 3px;
  padding: 0 3px;
  color: var(--orange);
}
.hb-body pre {
  margin: 6px 0;
  padding: 7px 8px;
  max-height: 260px;
  overflow: auto;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 4px;
  font: 10.5px/1.45 Menlo, "SF Mono", monospace;
  color: var(--text-dim);
  white-space: pre;
}
.hb-body pre.res { border-color: var(--blue-mid); color: var(--blue); white-space: pre-wrap; }
.hb-body pre.res.err { border-color: var(--danger-mid); color: var(--danger); }
.hb-body ul { margin: 0 0 6px; padding-left: 16px; }
.hb-body li { margin: 0 0 2px; }
.hb-body h4 { margin: 6px 0 4px; font-size: 11px; color: var(--orange); letter-spacing: 0.3px; }

.hb-run { display: flex; justify-content: flex-end; margin: -2px 0 6px; }
.hb-run .tile.chip { min-height: 22px; }

.hb-caret {
  display: inline-block;
  width: 6px; height: 11px;
  margin-left: 2px;
  vertical-align: -1px;
  background: var(--orange);
  animation: hbBlink 1s steps(1) infinite;
}
@keyframes hbBlink { 50% { opacity: 0; } }

.hb-think {
  font-size: 10px;
  color: var(--text-muted);
  font-style: italic;
}

/* tool rows */
.hb-tools:empty { display: none; }
.hb-tools { margin-top: 6px; display: flex; flex-direction: column; gap: 2px; }
.hb-tool {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 9.5px/1.3 Menlo, "SF Mono", monospace;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hb-tool i {
  width: 6px; height: 6px; border-radius: 50%;
  flex: 0 0 auto;
  background: var(--orange);
  box-shadow: 0 0 5px var(--orange-mid);
  animation: hbBlink 0.8s steps(1) infinite;
}
.hb-tool.done i { background: var(--blue); box-shadow: none; animation: none; }
.hb-tool.fail i { background: var(--danger); box-shadow: none; animation: none; }
.hb-tool.ae { color: var(--text-dim); }
.hb-tool b { color: var(--orange); font-weight: 700; }

.hb-note {
  margin: 0 0 7px;
  padding: 3px 8px;
  border-left: 2px solid var(--stroke);
  font-size: 9.5px;
  color: var(--text-muted);
}
.hb-note.err { border-color: var(--danger); color: var(--danger); }

/* permission card */
.hb-perm {
  margin: 0 0 7px;
  padding: 7px 9px 8px;
  border-radius: 5px;
  border: 1px solid var(--orange-mid);
  background: var(--orange-dim);
}
.hb-perm .hb-who { margin-bottom: 4px; }
.hb-perm pre {
  margin: 0 0 6px;
  max-height: 90px;
  overflow: auto;
  font: 9.5px/1.4 Menlo, monospace;
  color: var(--text-dim);
  white-space: pre-wrap;
}
.hb-perm .row { display: flex; gap: 5px; flex-wrap: wrap; }
.hb-perm.done { opacity: 0.5; pointer-events: none; }

/* ---------- composer ---------- */
.hb-composer { display: flex; gap: 6px; align-items: stretch; }
.hb-composer textarea {
  flex: 1 1 auto;
  min-height: 46px;
  max-height: 160px;
  resize: none;
  padding: 6px 8px;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 4px;
  color: var(--text);
  font-family: inherit;
  font-size: 11.5px;
  line-height: 1.4;
  outline: none;
  user-select: text;
  cursor: text;
  transition: border-color 0.14s ease, box-shadow 0.14s ease;
}
.hb-composer textarea:focus { border-color: var(--orange); box-shadow: 0 0 0 2px var(--orange-dim); }
.hb-composer textarea::placeholder { color: var(--text-muted); }

.hb-send { width: 56px; min-height: 46px; flex: 0 0 auto; }
.hb-send.is-stop { --accent: var(--danger); --accent-dim: var(--danger-dim); --accent-mid: var(--danger-mid); border-color: var(--danger-mid); color: var(--danger); }

.hb-hint {
  display: flex;
  justify-content: space-between;
  margin-top: 5px;
  font-size: 9px;
  color: var(--text-muted);
}

/* ---------- log drawer ---------- */
.hb-drawer {
  margin: 8px 0 0;
  max-height: 160px;
  overflow: auto;
  padding: 6px 7px;
  background: var(--field);
  border: 1px solid var(--stroke-soft);
  border-radius: 4px;
  font: 9px/1.35 Menlo, monospace;
  color: var(--text-muted);
  white-space: pre-wrap;
  user-select: text;
}

.led.busy { background: var(--blue); box-shadow: 0 0 6px var(--blue-mid); animation: hbBlink 0.9s steps(1) infinite; }

/* ---------- model switch ---------- */
.card-head { position: relative; }
.hb-mchip {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 5px;
  max-width: 62%;
  height: 20px;
  padding: 0 6px 0 7px;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 10px;
  color: var(--text);
  font-family: inherit;
  font-size: 9.5px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.13s ease, background 0.13s ease;
}
.hb-mchip:hover, .hb-mchip.open { border-color: var(--orange); background: var(--tile-hover); }
.hb-mchip span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.hb-mchip em { font-style: normal; font-weight: 400; color: var(--text-muted); white-space: nowrap; }
.hb-mchip svg { width: 10px; height: 10px; flex: 0 0 auto; color: var(--text-muted); transition: transform 0.15s ease; }
.hb-mchip.open svg { transform: rotate(180deg); }
.hb-mchip .dot, .hb-mrow .dot {
  width: 6px; height: 6px; border-radius: 50%; flex: 0 0 auto;
  background: var(--orange); box-shadow: 0 0 5px var(--orange-mid);
}
.hb-mchip.switching .dot { background: var(--blue); box-shadow: 0 0 5px var(--blue-mid); animation: hbBlink 0.7s steps(1) infinite; }
.hb-mchip.bad .dot { background: var(--danger); box-shadow: 0 0 5px var(--danger-mid); }
.hb-mchip.switching { pointer-events: none; opacity: 0.8; }

.hb-picker {
  margin: 4px 0 8px;
  background: var(--field);
  border: 1px solid var(--orange-mid);
  border-radius: 5px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
  overflow: hidden;
  animation: hbDrop 0.14s cubic-bezier(0.2, 0.9, 0.3, 1);
}
@keyframes hbDrop { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

.hb-msearch {
  width: 100%;
  padding: 7px 9px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--stroke-soft);
  color: var(--text);
  font-family: inherit;
  font-size: 11px;
  outline: none;
  user-select: text;
}
.hb-msearch::placeholder { color: var(--text-muted); }

.hb-mlist { max-height: 300px; overflow-y: auto; overscroll-behavior: contain; padding: 3px 0; }
.hb-mlist::-webkit-scrollbar { width: 8px; }
.hb-mlist::-webkit-scrollbar-thumb { background: #3a3a44; border-radius: 4px; border: 2px solid var(--field); }

.hb-mhead {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 9px 3px;
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.55px;
  text-transform: uppercase;
  color: var(--text-muted);
}
.hb-mhead[data-p] { cursor: pointer; }
.hb-mhead[data-p]:hover { color: var(--text-dim); }
.hb-mhead span { font-weight: 400; text-transform: none; letter-spacing: 0; opacity: 0.8; }
.hb-mhead .n { margin-left: auto; font-variant-numeric: tabular-nums; }
.hb-mhead .chev {
  width: 0; height: 0;
  border-left: 4px solid currentColor;
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  transition: transform 0.12s ease;
}
.hb-mhead .chev.open { transform: rotate(90deg); }

.hb-mrow {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 6px 4px 11px;
  font-size: 11px;
  color: var(--text-dim);
  cursor: pointer;
}
.hb-mrow .dot { background: transparent; box-shadow: none; border: 1px solid var(--stroke); }
.hb-mrow.on .dot { background: var(--orange); border-color: var(--orange); box-shadow: 0 0 5px var(--orange-mid); }
.hb-mrow.on { color: var(--text); font-weight: 600; }
.hb-mrow:hover, .hb-mrow.cur { background: var(--tile-hover); color: var(--text); }
.hb-mrow .nm { flex: 1 1 auto; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hb-mrow .pv { font-style: normal; font-size: 9px; color: var(--text-muted); white-space: nowrap; }
.hb-mrow .warn { font-size: 8.5px; font-weight: 700; color: var(--danger); white-space: nowrap; }
.hb-mrow.bad .nm { color: var(--text-muted); text-decoration: line-through; text-decoration-color: var(--danger-mid); }

.hb-mstar {
  display: flex; align-items: center; justify-content: center;
  width: 18px; height: 18px; padding: 0;
  background: transparent; border: 0;
  color: var(--stroke);
  cursor: pointer;
  opacity: 0;
  transition: color 0.12s ease, opacity 0.12s ease;
}
.hb-mstar svg { width: 11px; height: 11px; }
.hb-mrow:hover .hb-mstar, .hb-mstar.on { opacity: 1; }
.hb-mstar:hover { color: var(--orange-mid); }
.hb-mstar.on { color: var(--orange); }

.hb-mempty { padding: 14px 10px; text-align: center; font-size: 10px; color: var(--text-muted); }
.hb-mfoot {
  display: flex; justify-content: space-between; gap: 8px;
  padding: 4px 9px;
  border-top: 1px solid var(--stroke-soft);
  font-size: 8.5px; color: var(--text-muted);
}

/* favourites strip in SESSION */
.hb-favs:empty { display: none; }
.hb-favs { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px; margin-bottom: 6px; }
.hb-favs .tile.chip { justify-content: flex-start; }
.hb-favs .tile.chip span { font-size: 8.5px; }

/* system line in the chat when the model changes */
.hb-switch {
  display: flex; align-items: center; gap: 7px;
  margin: 2px 0 9px;
  font-size: 8.5px; font-weight: 700; letter-spacing: 0.5px;
  color: var(--blue);
  text-transform: uppercase;
}
.hb-switch::before, .hb-switch::after { content: ""; flex: 1 1 auto; height: 1px; background: var(--blue-mid); }
.hb-msg .hb-who .mdl { margin-left: auto; font-weight: 400; letter-spacing: 0; color: var(--text-muted); text-transform: none; }

[data-theme="light"] .hb-log::-webkit-scrollbar-thumb { background: #d4ae97; }

/* v2: per-call timing on AE tool rows */
.hb-tool .ms { margin-left: auto; padding-left: 8px; color: var(--text-muted); font-variant-numeric: tabular-nums; }

/* v2.1: image attachments */
.hb-attach { display: none; gap: 6px; flex-wrap: wrap; padding: 0 0 6px; }
.hb-athumb { position: relative; width: 56px; height: 56px; border: 1px solid var(--border); border-radius: 4px; overflow: hidden; background: var(--bg-2, #111); }
.hb-athumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hb-athumb button { position: absolute; top: 2px; right: 2px; width: 16px; height: 16px; line-height: 14px; padding: 0; border: 0; border-radius: 50%; background: rgba(0,0,0,.7); color: #fff; font-size: 10px; cursor: pointer; }
.hb-uimg { display: block; max-width: 160px; max-height: 120px; margin-top: 6px; border: 1px solid var(--border); border-radius: 4px; }
body.hb-dropping .hb-composer textarea { border-color: var(--orange); box-shadow: 0 0 0 2px var(--orange-dim); }

/* setup (first run) */
.hb-setup { border: 1px solid var(--stroke); border-radius: 6px; padding: 12px; margin: 6px 0 8px; }
.hb-setup h3 { margin: 0 0 6px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; }
.hb-setup p { margin: 0 0 8px; color: var(--text-muted); font-size: 11px; line-height: 1.45; }
.hb-steps { margin: 0 0 10px; padding-left: 18px; font-size: 11px; line-height: 1.8; color: var(--text-muted); }
.hb-steps li.now { color: var(--text); font-weight: 600; }
.hb-steps li.done { color: var(--text-muted); text-decoration: line-through; }
.hb-setup-act { display: flex; gap: 6px; margin-bottom: 8px; }
.hb-setup-act .tile { flex: 1; justify-content: center; }
.hb-setup-note { font-size: 10px !important; }

/* ---------------------------------------------------------
   PERF (typing lag). CEP renders this panel offscreen and the host app
   (AE / Premiere) copies every frame on its main thread - the thread that
   also delivers keystrokes. The shared idle loops from panel.css (logo
   float, pixel ticker marquee, emoji bob/flicker: ~100 running animations)
   kept the panel repainting non-stop: measured ~10% host CPU while idle,
   ~0% with them off. Hermes is a typing panel, so idle loops stay off here.
   Click/hover/status/streaming animations still run.
   --------------------------------------------------------- */
.brand-logo:not(.logo-pop),
.brand-logo .fg-l2,
.brand-logo .fg-l4,
.feugee-ticker-track,
.pixel-text,
.pixel-icon { animation: none !important; }

/* profile picker (SESSION card) */
.hb-prof { display: flex; align-items: center; gap: 8px; margin: 2px 0 8px; font-size: 10px; letter-spacing: 1.2px; color: var(--muted, #8a8a92); }
.hb-prof select {
  flex: 1; min-width: 0; height: 26px; padding: 0 8px;
  background: var(--field); color: inherit; border: 1px solid var(--stroke); border-radius: 6px;
  font: inherit; font-size: 11px; letter-spacing: 0.2px;
}
.hb-prof select:focus { outline: none; border-color: var(--blue); }

/* ---- Envato results (envato_search) ---------------------------------- */
.hb-tool.env b { color: var(--blue); }
.hb-link { color: var(--blue); text-decoration: underline; text-underline-offset: 2px; cursor: pointer; word-break: break-all; }
.hb-link:hover { color: var(--orange); }
.hb-env { margin: 6px 0 2px; }
.hb-env-h { font: 9.5px/1.3 Menlo, "SF Mono", monospace; color: var(--text-dim); margin-bottom: 5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hb-env-h b { color: var(--blue); font-weight: 700; }
.hb-env-h span { color: var(--text-muted); }
.hb-env-g { display: grid; grid-template-columns: repeat(auto-fill, minmax(104px, 1fr)); gap: 6px; }
.hb-env-c {
  position: relative; display: flex; flex-direction: column; align-items: stretch; gap: 2px;
  padding: 0 0 5px; margin: 0; text-align: left; cursor: pointer;
  background: var(--field); border: 1px solid var(--stroke); border-radius: 4px; overflow: hidden;
  color: var(--text); font: inherit;
}
.hb-env-c:hover { border-color: var(--blue); }
.hb-env-c img, .hb-env-c em {
  display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: cover; background: var(--tile);
}
.hb-env-c em {
  display: flex; align-items: center; justify-content: center; font-style: normal;
  font: 9px/1 Menlo, "SF Mono", monospace; color: var(--text-muted); text-transform: uppercase; letter-spacing: .06em;
}
.hb-env-c .n {
  position: absolute; top: 4px; left: 4px; min-width: 14px; padding: 1px 3px; border-radius: 3px;
  background: var(--bg); color: var(--text); font: 9px/1.2 Menlo, "SF Mono", monospace; text-align: center;
}
.hb-env-c .t { padding: 0 6px; font-size: 10.5px; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.hb-env-c .a { padding: 0 6px; font: 9px/1.2 Menlo, "SF Mono", monospace; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

