    if (!p && window.location && window.location.pathname) {
      p = window.location.pathname.replace(/\/[^\/]+$/, "");
    }
    if (p) {
      p = decodeURIComponent(p.replace(/^file:\/\//i, "")).replace(/\\/g, "/");
      if (/^\/[a-zA-Z]:/.test(p)) {
        p = p.substring(1);
      }
