    var done = "Selesai. Balik ke " + APP + " dan klik CEK LAGI di panel Hermes Bridge PR.";
    if (WIN) {
      var p = path.join(BASE, name + ".ps1");
      var body = [
        "$ErrorActionPreference = 'Continue'",
        "$Host.UI.RawUI.WindowTitle = " + psQuote("Hermes Bridge PR - " + step.title),
        "[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor 3072",
        "Write-Host ''",
        "Write-Host " + psQuote("  HERMES BRIDGE PR - " + step.title)
      ].concat(step.info.map(function (l) { return "Write-Host " + psQuote("  " + l); }))
       .concat(["Write-Host ''", step.ps, "Write-Host ''", "Write-Host " + psQuote("  " + done),
